const fs = require("fs");
const path = require("path");

// ─── Load pre-computed embeddings (generated by RAG/ingestion_pipeline.py) ────
// Cached across warm Lambda invocations on Vercel.
let CHUNKS = null;

function getChunks() {
  if (!CHUNKS) {
    try {
      const p = path.join(__dirname, "vectorstore.json");
      CHUNKS = JSON.parse(fs.readFileSync(p, "utf-8"));
    } catch {
      CHUNKS = []; // fall through to keyword router if JSON not yet generated
    }
  }
  return CHUNKS;
}

// ─── Vector math ───────────────────────────────────────────────────────────────
function cosineSimilarity(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na  += a[i] * a[i];
    nb  += b[i] * b[i];
  }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

async function embedQuery(query, apiKey) {
  const res = await fetch("https://api.openai.com/v1/embeddings", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({ model: "text-embedding-3-small", input: query }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error?.message || "Embedding request failed");
  return data.data[0].embedding;
}

function retrieveTopChunks(queryVec, chunks, k = 4) {
  return chunks
    .map((c) => ({ text: c.text, score: cosineSimilarity(queryVec, c.embedding) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k)
    .map((c) => c.text);
}

