const ALL_SIGNAL_WORDS = [
  ...new Set(KNOWLEDGE_BASE.flatMap((e) => e.topics)),
  "skill", "project", "intern", "work", "experience", "hire", "background",
  "resume", "portfolio", "degree", "job", "role", "position", "company",
];

function isOffTopic(query) {
  return !ALL_SIGNAL_WORDS.some((w) => query.includes(w));
}

function keywordFallback(query) {
  if (isOffTopic(query)) {
    return "I can only answer questions about Samiur Rahman. Try asking about his internships, projects, or skills.";
  }
  let best = null, bestScore = 0;
  for (const entry of KNOWLEDGE_BASE) {
    const score = entry.topics.filter((t) => query.includes(t)).length;
    if (score > bestScore) { bestScore = score; best = entry; }
  }
  return best
    ? best.answer
    : "I'm Samiur Rahman — Computer Engineering @ Georgia Tech, with internships at Figure, Tesla, Tektronix, and Citadel. Ask about a specific role, project, or skill.";
}

// ─── Vercel serverless handler ────────────────────────────────────────────────
module.exports = async (req, res) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");

  if (req.method === "OPTIONS") return res.status(200).end();
  if (req.method !== "POST") {
    return res.status(405).json({ status: 405, response: "Method not allowed" });
  }

  const { query } = req.body || {};
  const trimmed = String(query || "").trim();

  if (trimmed === "__debug") {
    const chunks = getChunks();
    return res.status(200).json({
      status: 200,
      hasKey: !!process.env.OPENAI_API_KEY,
      keyLength: process.env.OPENAI_API_KEY?.length || 0,
      embeddingsLoaded: chunks.length > 0,
      chunkCount: chunks.length,
      model: "gpt-4o-mini",
      embeddingModel: "text-embedding-3-small",
    });
  }

  if (!trimmed) {
    return res.status(400).json({ status: 400, response: "Please enter a question." });
  }

  const apiKey = process.env.OPENAI_API_KEY;

  // ── RAG path ─────────────────────────────────────────────────────────────────
  if (apiKey) {
    const chunks = getChunks();

    try {
      // Step 1: embed the query
      const queryVec = await embedQuery(trimmed, apiKey);

      // Step 2: retrieve top-5 most relevant resume chunks
      const topChunks = chunks.length > 0
        ? retrieveTopChunks(queryVec, chunks, 5)
        : ["(no resume context available — please run ingestion_pipeline.py)"];

      const context = topChunks.join("\n\n---\n\n");
      const systemMsg = SYSTEM_PROMPT.replace("{context}", context);

      // Step 3: generate answer grounded in retrieved context
      const openaiRes = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          model: "gpt-4o-mini",
          messages: [
            { role: "system", content: systemMsg },
            { role: "user", content: trimmed },
          ],
          max_tokens: 200,
          temperature: 0.2,
        }),
      });

      const data = await openaiRes.json();

      if (openaiRes.ok) {
        const text = data.choices?.[0]?.message?.content?.trim();
        if (text) {
          return res.status(200).json({
            status: 200,
            response: text,
            source: "rag",
            chunksUsed: topChunks.length,
          });
        }
      } else {
        console.error("OpenAI error:", openaiRes.status, JSON.stringify(data));
        return res.status(200).json({
          status: 200,
          response: keywordFallback(trimmed.toLowerCase()),
          source: "fallback",
          llmError: data.error?.message || `HTTP ${openaiRes.status}`,
        });
      }
    } catch (err) {
      console.error("RAG error:", err.message);
    }
  }

  // ── Keyword fallback ─────────────────────────────────────────────────────────
  return res.status(200).json({
    status: 200,
    response: keywordFallback(trimmed.toLowerCase()),
    source: "fallback",
  });
};
